pub fn resolve(hashcode: u32) -> Option<&'static str> {
    ROBOTS_HASHDB
        .binary_search_by_key(&hashcode, |(value, _)| *value)
        .ok()
        .map(|index| ROBOTS_HASHDB[index].1)
}

pub trait IntoRobotsHashcode {
    fn into_robots_hashcode(self) -> u32;
}

impl IntoRobotsHashcode for u32 {
    fn into_robots_hashcode(self) -> u32 {
        self
    }
}

impl IntoRobotsHashcode for &u32 {
    fn into_robots_hashcode(self) -> u32 {
        *self
    }
}

impl IntoRobotsHashcode for i32 {
    fn into_robots_hashcode(self) -> u32 {
        self as u32
    }
}

impl IntoRobotsHashcode for &i32 {
    fn into_robots_hashcode(self) -> u32 {
        *self as u32
    }
}

pub fn format_or_invalid<T: IntoRobotsHashcode>(hashcode: T) -> String {
    let hashcode = hashcode.into_robots_hashcode();
    resolve(hashcode)
        .map(str::to_owned)
        .unwrap_or_else(|| format!("HT_Invalid_{hashcode:08x}"))
}
